nextflow_process {

    name "Test Process MALT_BUILD"
    script "../main.nf"
    config "./nextflow.config"
    process "MALT_BUILD"

    tag "modules"
    tag "modules_nfcore"
    tag "malt"
    tag "malt/build"

    test("sarscov2 - fastq - mdb") {
        def mapping_db
        setup {
            mapping_db = extract('s3://nf-core-test-datasets/modules/data/delete_me/malt/megan-nucl-Feb2022.db.zip')
        }

        when {
            params {
                module_args = '-J-Xmx6G --sequenceType DNA'
            }
            process {
                """
                def genome_1 = file(params.modules_testdata_base_path + 'genomics/prokaryotes/metagenome/fasta/sarscov2.fasta', checkIfExists: true )
                def genome_2 = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true )

                input[0] = [
                    [id: "test"],
                    [genome_1,genome_2]
                ]
                input[1] = []
                input[2] = file('${mapping_db}')
                input[3] = 'mdb'
                """
            }
        }

        then {

            assertAll(
                { assert process.success },
                { assert path(process.out.log[0][1]).readLines().last().contains("Peak memory") },
                { assert snapshot(
                    path("${process.out.index[0][1]}/index0.idx"),
                    path("${process.out.index[0][1]}/ref.db"),
                    path("${process.out.index[0][1]}/ref.idx"),
                    path("${process.out.index[0][1]}/ref.inf"),
                    path("${process.out.index[0][1]}/taxonomy.idx"),
                    path("${process.out.index[0][1]}/taxonomy.map"),
                    path("${process.out.index[0][1]}/taxonomy.tre"),
                    sanitizeOutput(process.out, unstableKeys:["log", "index"])
                ).match() }
            )
        }
    }

    test("sarscov2 - fastq - abin") {
        def mapping_db
        setup {
            mapping_db = extract('https://ngi-igenomes.s3.eu-west-1.amazonaws.com/test-data/createtaxdb/taxonomy/nucl_acc2tax-Jul2019.abin.zip')
        }

        when {
            params {
                module_args = '-J-Xmx6G --sequenceType DNA'
            }
            process {
                """
                def genome_1 = file(params.modules_testdata_base_path + 'genomics/prokaryotes/metagenome/fasta/sarscov2.fasta', checkIfExists: true )
                def genome_2 = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true )

                input[0] = [
                    [id: "test"],
                    [genome_1,genome_2]
                ]
                input[1] = []
                input[2] = file('${mapping_db}')
                input[3] = 'a2t'
                """
            }
        }

        then {

            assertAll(
                { assert process.success },
                { assert path(process.out.log[0][1]).readLines().last().contains("Peak memory") },
                { assert snapshot(
                    path("${process.out.index[0][1]}/index0.idx"),
                    path("${process.out.index[0][1]}/ref.db"),
                    path("${process.out.index[0][1]}/ref.idx"),
                    path("${process.out.index[0][1]}/ref.inf"),
                    path("${process.out.index[0][1]}/taxonomy.idx"),
                    path("${process.out.index[0][1]}/taxonomy.map"),
                    path("${process.out.index[0][1]}/taxonomy.tre"),
                    sanitizeOutput(process.out, unstableKeys:["log", "index"])
                ).match() }
            )
        }

    }

    test("sarscov2 - fastq - stub") {
        options "-stub"

        when {
            params {
                module_args = ''
            }
            process {
                """
                def genome_1 = file(params.modules_testdata_base_path + 'genomics/prokaryotes/metagenome/fasta/sarscov2.fasta', checkIfExists: true )
                def genome_2 = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true )

                input[0] = [
                    [id: "test"],
                    [genome_1,genome_2]
                ]
                input[1] = []
                input[2] = []
                input[3] = 'mdb'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

